// Open Graph image untuk preview link (WhatsApp/Telegram/dll).
// Gambar 1200x630 ditanam base64 di sini karena push GitHub hanya menerima
// file teks — file JPG biner tidak bisa di-push langsung. Disajikan sebagai
// image/jpeg dari /api/og-image (lihat og:image di index.html).
const IMG = Buffer.from("", "base64");
export default function handler(req, res) {
  res.setHeader("Content-Type", "image/jpeg");
  res.setHeader("Cache-Control", "public, max-age=86400, s-maxage=86400");
  res.setHeader("Content-Length", IMG.length);
  res.status(200).end(IMG);
}
